'use strict';
function accessory(base,lines,rank,price){if(!Number.isFinite(base)||base<0||!Number.isInteger(lines)||lines<1||lines>3||!Number.isInteger(rank)||rank<0||rank>11||!Number.isFinite(price)||price<=0)throw Error('基础值须为非负数，词条数为1–3，锻数为0–11整数，价格须大于0。');const value=base+4*lines*rank;return{value,unit:value>0?price/value:null}}
if(typeof module!=='undefined')module.exports={accessory};
if(typeof document!=='undefined'){
const el=id=>document.getElementById(id),fmt=n=>n.toLocaleString('zh-CN',{maximumFractionDigits:2});
const schools=[{name:'女儿村 / 雨落寒沙',sub:'女儿村 · 先看小怪伤害',items:['先检查暗器技巧、输出技能与法修，再决定装备预算。','装备关注敏捷、适用的伤害来源与固定伤害词条。','头部太阳石、灵饰伤害等来源与武器伤害不能未经核对就视为同一种转换。'],note:'看武器时，把伤害和命中分开。先弄清当前经脉算哪一部分，再比较两把武器，别直接照物理号的“综合伤害”挑。'},{name:'阴曹地府 / 阎罗令',sub:'地府 · 记得区分白天和夜间',items:['检查阎罗令相关技能和经脉，比较时保持昼夜状态一致。','敏捷、适用武器伤害、固伤灵饰与符石一起评估。','同时关注低防御、低气血带来的损失，不能为一项加敏牺牲整队稳定性。'],note:'今天白天测、明天夜里测，伤害变了未必是装备的原因。尽量在同一时段比较，点选目标和其他小怪也分开记。'},{name:'无底洞 / 夺命咒',sub:'无底洞 · 先想好平时怎么用',items:['输出流派和治疗辅助流派需要不同配置侧重。','日常输出看当前流派适用的敏捷与固伤属性；辅助职责看速度、生存与治疗需求。','特技、愤怒腰带等应匹配实际战斗安排，不能只凭标签购买。'],note:'平时主要秒怪，就围绕输出配；经常负责治疗、救人，就多留意速度和生存。先想好这个号怎么用，装备才好挑。'}];
function show(i){const s=schools[i];el('school-sub').textContent=s.sub;el('school-title').textContent=s.name;el('school-list').innerHTML=s.items.map(x=>'<li>'+x+'</li>').join('');el('school-note').textContent=s.note;document.querySelectorAll('.tab').forEach((e,j)=>{e.classList.toggle('selected',i===j);e.setAttribute('aria-selected',String(i===j))})}document.querySelectorAll('[data-school]').forEach(e=>e.onclick=()=>show(+e.dataset.school));show(0);
el('compare-fields').innerHTML=['A','B'].map((n,i)=>[['base','固伤基础值合计',i?22:18,0,10000],['lines','固定伤害词条数',2,1,3],['rank','星辉锻数',i?5:4,0,11],['price','成品价格（万两）',i?700:500,.1,10000000]].map(([key,label,v,min,max])=>'<label class="field">'+n+' · '+label+'<input type="number" id="'+n+'-'+key+'" min="'+min+'" max="'+max+'" value="'+v+'" step="'+(key==='price'?'0.1':'1')+'"></label>').join('')).join('');
function calculate(){try{const results=['A','B'].map(n=>{const fields=['base','lines','rank','price'].map(k=>{const v=el(n+'-'+k).value;if(!v.trim())throw Error('请填完整两件灵饰的输入项。');return Number(v)});return accessory(...fields)});el('compare-error').textContent='';el('compare-results').innerHTML=results.map((r,i)=>'<div class="result"><strong>'+fmt(r.value)+'</strong><span>'+['A','B'][i]+' · 成品固定伤害属性合计</span></div><div class="result"><strong>'+(r.unit===null?'—':fmt(r.unit))+'</strong><span>'+['A','B'][i]+' · 每点属性价格（万两）</span></div>').join('');const diff=results[1].value-results[0].value;el('compare-note').textContent='B 相比 A 的固定伤害属性'+(diff>=0?'增加 ':'减少 ')+fmt(Math.abs(diff))+' 点。这只是属性差值，不是每个目标的实战伤害差值；其他有效词条与生存需求仍需另行比较。'}catch(e){el('compare-error').textContent=e.message;el('compare-results').innerHTML='';el('compare-note').textContent='请修正输入后查看对比结果。'}}document.querySelectorAll('#compare-fields input').forEach(e=>e.addEventListener('input',calculate));calculate();
const checks=['确认装备等级与角色等级相符','确认性别、武器造型及专用等穿戴条件','查看武器伤害和敏捷，不只看命中','确认衣服敏捷附加与基础防御','查看门派固伤符石组合是否正确','核对孔数、符石颜色顺序和耐久','确认套装能与现有装备凑成三件或五件','核对灵饰固伤词条数、数值和星辉锻数','比较成品总价，包括后续强化费用','确认技能、经脉和符石规则适用于当前时间服'];let state=[];try{state=JSON.parse(localStorage.getItem('lesson3-checks-v2')||'[]');if(!Array.isArray(state))state=[]}catch{}el('shopping-list').innerHTML=checks.map((x,i)=>'<p><label><input type="checkbox" data-check="'+i+'" '+(state[i]?'checked':'')+'> '+x+'</label></p>').join('');function count(){el('check-status').textContent='验货清单：已确认 '+checks.filter((_,i)=>state[i]).length+' / '+checks.length+' 项（仅保存在当前浏览器）'}document.querySelectorAll('[data-check]').forEach(e=>e.onchange=()=>{state[+e.dataset.check]=e.checked;try{localStorage.setItem('lesson3-checks-v2',JSON.stringify(state))}catch{}count()});count();
let done=false;try{done=localStorage.getItem('lesson3-complete')==='1'}catch{}function paint(){el('complete').textContent=done?'第三课已学完 ✓ · 点击重置':'标记第三课已学完 ✓'}el('complete').onclick=()=>{done=!done;try{localStorage.setItem('lesson3-complete',done?'1':'0')}catch{}paint()};paint();const sections=[...document.querySelectorAll('section')];function progress(){const p=Math.min(100,Math.round(window.scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight)*100));el('progress').value=p;el('progress-label').textContent='阅读进度 '+p+'%';let id=sections[0].id;sections.forEach(s=>{if(s.getBoundingClientRect().top<innerHeight*.35)id=s.id});document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+id))}addEventListener('scroll',progress,{passive:true});progress();
}
